// Last 7 days of chat activity, leaving out automated test runs (sessions starting "eval-" or "check-").
const tz = "America/New_York";
const now = DateTime.now().setZone(tz);
const since = now.minus({ days: 7 });
const isTest = s => /^(eval|check)-/.test(String(s ?? ""));
const recent = (name, field) => $(name).all()
  .map(i => i.json)
  .filter(r => r[field] && DateTime.fromISO(String(r[field])) >= since && !isTest(r.session_id));

const conversations = recent("Read Conversations", "timestamp");
const bookings = recent("Read Bookings", "created_at");
const tickets = recent("Read Tickets", "created_at");
const unanswered = recent("Read Unanswered", "timestamp");

const countBy = (rows, key) => Object.entries(rows.reduce((m, r) => {
  const k = r[key] || "other";
  m[k] = (m[k] || 0) + 1;
  return m;
}, {})).sort((a, b) => b[1] - a[1]);
const questions = [...new Set(unanswered.map(r => String(r.question).trim()).filter(Boolean))].slice(0, 40);

return [{
  json: {
    week_label: since.toFormat("LLL d") + " to " + now.toFormat("LLL d, yyyy"),
    chats: new Set(conversations.map(r => r.session_id)).size,
    messages: conversations.length,
    errors: conversations.filter(r => String(r.tools_used).startsWith("error")).length,
    bookings: bookings.length,
    bookings_by_service: countBy(bookings, "service"),
    handoffs: tickets.length,
    handoffs_by_reason: countBy(tickets, "reason"),
    open_tickets: tickets.filter(r => r.status === "open").length,
    unanswered_count: unanswered.length,
    questions_text: questions.length ? questions.map(q => "- " + q).join("\n") : "(none)"
  }
}];

// The AI returns plain "Theme | count | suggestion" lines; everything is escaped here, so customer text can't inject HTML.
const s = $("Build Stats").first().json;
const esc = v => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const row = (label, value) => "<tr><td>" + esc(label) + "</td><td><b>" + esc(value) + "</b></td></tr>";
const list = pairs => pairs.length
  ? "<ul>" + pairs.map(([k, n]) => "<li>" + esc(String(k).replaceAll("_", " ")) + ": " + n + "</li>").join("") + "</ul>"
  : "<p>None this week.</p>";

const themes = String($input.first().json.output ?? "")
  .split("\n")
  .map(line => line.split("|").map(part => part.trim()))
  .filter(parts => parts.length >= 3 && parts[0]);
const themesHtml = themes.length
  ? "<ul>" + themes.map(([theme, count, suggestion]) => "<li><b>" + esc(theme) + "</b> (" + esc(count) + "): " + esc(suggestion) + "</li>").join("") + "</ul>"
  : "<p>No unanswered questions this week.</p>";

const html = [
  "<h2>Copperline chat assistant: weekly report</h2>",
  "<p>" + esc(s.week_label) + "</p>",
  "<table cellpadding='6' style='border-collapse:collapse'>",
  row("Chats", s.chats),
  row("Messages", s.messages),
  row("Bookings made", s.bookings),
  row("Passed to the team", s.handoffs + " (" + s.open_tickets + " still open)"),
  row("Questions it couldn't answer", s.unanswered_count),
  row("Errors", s.errors),
  "</table>",
  "<h3>Bookings by service</h3>",
  list(s.bookings_by_service),
  "<h3>Hand-offs by reason</h3>",
  list(s.handoffs_by_reason),
  "<h3>What to add to the shop info</h3>",
  themesHtml,
  "<p style='color:#666'>Edit the shop info Google Doc and the assistant picks up the change within 5 minutes.</p>"
].join("\n");

return [{ json: { subject: "Copperline chat assistant: " + s.week_label, html } }];
